AND business_date BETWEEN #{p.startDate} AND #{p.endDate}
AND entry_type=#{p.entryType}
AND funding_channel_id=#{p.fundingId}
AND search_text ILIKE #{p.keyword} ESCAPE '\'

mapper.select:
WITH adjustment_totals AS ( SELECT original_expense_id,sum(amount) AS effective_total FROM expense_adjustment WHERE status='EFFECTIVE' GROUP BY original_expense_id ), items AS ( SELECT l.id,l.entry_type,l.business_time,l.business_date,l.created_at, CASE WHEN l.entry_type='EXPENSE' THEN l.product_name_snapshot ELSE l.income_name END AS title, CASE WHEN l.entry_type='EXPENSE' THEN concat_ws(' / ',l.primary_category_name_snapshot,l.secondary_category_name_snapshot) ELSE l.income_category_name_snapshot END AS category_name, CASE WHEN l.entry_type='EXPENSE' THEN concat_ws(' · ',l.quantity || ' ' || l.unit_name_snapshot, l.purchase_channel_name_snapshot,l.location_label_name_snapshot) ELSE l.payer_name_snapshot END AS counterparty_name, l.funding_channel_id,l.funding_channel_name_snapshot, CASE WHEN l.entry_type='EXPENSE' THEN l.paid_amount ELSE l.income_amount END AS amount,l.note, CAST(NULL AS varchar) AS adjustment_type,CAST(NULL AS uuid) AS original_expense_id, CASE WHEN l.entry_type='EXPENSE' THEN COALESCE(t.effective_total,0) END AS effective_adjustment_amount, CASE WHEN l.entry_type='EXPENSE' THEN l.paid_amount-COALESCE(t.effective_total,0) END AS net_expense_amount, l.entry_type='EXPENSE' AND COALESCE(t.effective_total,0)=l.paid_amount AS fully_adjusted, l.version,'ACTIVE' AS lifecycle_status,CAST(NULL AS timestamptz) AS deleted_at, CAST(NULL AS timestamptz) AS purge_after,CAST(NULL AS integer) AS remaining_days,0 AS linked_count, concat_ws(' ',l.product_name_snapshot,l.primary_category_name_snapshot,l.secondary_category_name_snapshot, l.income_name,l.payer_name_snapshot,l.income_category_name_snapshot,l.funding_channel_name_snapshot, l.purchase_channel_name_snapshot,l.location_label_name_snapshot,l.note) AS search_text FROM ledger_entry l LEFT JOIN adjustment_totals t ON t.original_expense_id=l.id WHERE l.lifecycle_status='ACTIVE' UNION ALL SELECT a.id,'ADJUSTMENT',a.business_time,a.business_date,a.created_at, CASE a.adjustment_type WHEN 'REFUND' THEN '退款' ELSE '报销' END, CASE a.adjustment_type WHEN 'REFUND' THEN '支出退款' ELSE '费用报销' END, '原支出 · ' || l.product_name_snapshot,l.funding_channel_id,l.funding_channel_name_snapshot, a.amount,a.note,a.adjustment_type,a.original_expense_id,t.effective_total, l.paid_amount-t.effective_total,t.effective_total=l.paid_amount,a.version,'EFFECTIVE', CAST(NULL AS timestamptz),CAST(NULL AS timestamptz),CAST(NULL AS integer),0, concat_ws(' ',l.product_name_snapshot,l.primary_category_name_snapshot,l.secondary_category_name_snapshot, l.funding_channel_name_snapshot,a.note,CASE a.adjustment_type WHEN 'REFUND' THEN '退款' ELSE '报销' END) FROM expense_adjustment a JOIN ledger_entry l ON l.id=a.original_expense_id AND l.lifecycle_status='ACTIVE' JOIN adjustment_totals t ON t.original_expense_id=a.original_expense_id WHERE a.status='EFFECTIVE' ) SELECT FROM items WHERE true
AND (business_date,business_time,created_at,id) < (#{p.cursorDate},#{p.cursorTime},#{p.cursorCreated},#{p.cursorId})
ORDER BY business_date DESC,business_time DESC,created_at DESC,id DESC LIMIT #{p.limit}
